import { log } from '../core/logger.js';
export function helpCommand() {
    log.banner();
    const colors = { bold: '\x1b[1m', dim: '\x1b[2m', cyan: '\x1b[36m', yellow: '\x1b[33m', reset: '\x1b[0m' };
    console.log(`${colors.bold}USAGE${colors.reset}`);
    console.log(`  webapkify <command> [options]\n`);
    console.log(`${colors.bold}COMMANDS${colors.reset}`);
    const commands = [
        ['build', 'Generate Android project + build debug APK'],
        ['build --release', 'Build signed release APK (requires signing config)'],
        ['clean', 'Remove the generated ./webapkify/ directory'],
        ['init', 'Scaffold webapkify.config.ts in current directory'],
        ['help', 'Show this help message'],
        ['version', 'Print webapkify version'],
        ['about', 'Show project info and how it works'],
    ];
    for (const [command, description] of commands)
        console.log(`  ${colors.cyan}${colors.bold}webapkify ${command.padEnd(22)}${colors.reset}${description}`);
    console.log();
    console.log(`${colors.bold}CONFIG${colors.reset}`);
    console.log(`  ${colors.dim}webapkify.config.ts${colors.reset} - place next to your dist/ directory`);
    console.log(`  Run ${colors.cyan}webapkify init${colors.reset} to generate a fully documented config.\n`);
    console.log(`${colors.bold}REQUIREMENTS${colors.reset}`);
    console.log(`  • JDK 17+      (JAVA_HOME or on PATH)`);
    console.log(`  • Android SDK  (ANDROID_HOME)`);
    console.log(`  • Gradle       (via gradlew wrapper - auto-bootstrapped)\n`);
    console.log(`${colors.bold}QUICK START${colors.reset}`);
    console.log(`  ${colors.yellow}webapkify init${colors.reset}`);
    console.log(`  ${colors.dim}# edit webapkify.config.ts, then build your web app${colors.reset}`);
    console.log(`  ${colors.yellow}webapkify build${colors.reset}`);
    console.log(`  ${colors.yellow}webapkify build --release${colors.reset}\n`);
}
